    45	    const validate = (values: FormOnyxValues<typeof ONYXKEYS.FORMS.DISPLAY_NAME_FORM>) => {
    46	        const errors: FormInputErrors<typeof ONYXKEYS.FORMS.DISPLAY_NAME_FORM> = {};
    47	
    48	        // First we validate the first name field
    49	        if (!ValidationUtils.isValidDisplayName(values.firstName)) {
    50	            ErrorUtils.addErrorMessage(errors, 'firstName', translate('personalDetails.error.hasInvalidCharacter'));
    51	        } else if (values.firstName.length > CONST.TITLE_CHARACTER_LIMIT) {
    52	            ErrorUtils.addErrorMessage(errors, 'firstName', translate('common.error.characterLimitExceedCounter', {length: values.firstName.length, limit: CONST.TITLE_CHARACTER_LIMIT}));
    53	        } else if (values.firstName.length === 0) {
    54	            ErrorUtils.addErrorMessage(errors, 'firstName', translate('personalDetails.error.requiredFirstName'));
    55	        }
    56	        if (ValidationUtils.doesContainReservedWord(values.firstName, CONST.DISPLAY_NAME.RESERVED_NAMES)) {
    57	            ErrorUtils.addErrorMessage(errors, 'firstName', translate('personalDetails.error.containsReservedWord'));
    58	        }
    59	
    60	        // Then we validate the last name field
    61	        if (!ValidationUtils.isValidDisplayName(values.lastName)) {
    62	            ErrorUtils.addErrorMessage(errors, 'lastName', translate('personalDetails.error.hasInvalidCharacter'));
    63	        } else if (values.lastName.length > CONST.TITLE_CHARACTER_LIMIT) {
    64	            ErrorUtils.addErrorMessage(errors, 'lastName', translate('common.error.characterLimitExceedCounter', {length: values.lastName.length, limit: CONST.TITLE_CHARACTER_LIMIT}));
    65	        }
    66	        if (ValidationUtils.doesContainReservedWord(values.lastName, CONST.DISPLAY_NAME.RESERVED_NAMES)) {
    67	            ErrorUtils.addErrorMessage(errors, 'lastName', translate('personalDetails.error.containsReservedWord'));
    68	        }
    69	        return errors;
    70	    };
    71	    return (
    72	        <ScreenWrapper
    73	            includeSafeAreaPaddingBottom={false}
    74	            shouldEnableMaxHeight
    75	            testID={DisplayNamePage.displayName}
    76	        >
    77	            <HeaderWithBackButton
    78	                title={translate('displayNamePage.headerTitle')}
    79	                onBackButtonPress={() => Navigation.goBack()}
    80	            />
    81	                <FormProvider
    82	                    style={[styles.flexGrow1, styles.ph5]}
    83	                    formID={ONYXKEYS.FORMS.DISPLAY_NAME_FORM}
    84	                    validate={validate}
    85	                    onSubmit={updateDisplayName}
    86	                    submitButtonText={translate('common.save')}
    87	                    enabledWhenOffline
    88	                    shouldValidateOnBlur
    89	                    shouldValidateOnChange
    90	                >
    91	                    <Text style={[styles.mb6]}>{translate('displayNamePage.isShownOnProfile')}</Text>
    92	                    <View style={styles.mb4}>
    93	                        <InputWrapper
    94	                            InputComponent={TextInput}
    95	                            inputID={INPUT_IDS.FIRST_NAME}
    96	                            name="fname"
    97	                            label={translate('common.firstName')}
    98	                            aria-label={translate('common.firstName')}
    99	                            role={CONST.ROLE.PRESENTATION}
   100	                            defaultValue={currentUserDetails.firstName ?? ''}
   101	                            spellCheck={false}
   102	                        />
   103	                    </View>
   104	                    <View>
   105	                        <InputWrapper
   106	                            InputComponent={TextInput}
   107	                            inputID={INPUT_IDS.LAST_NAME}
   108	                            name="lname"
   109	                            label={translate('common.lastName')}
   110	                            aria-label={translate('common.lastName')}
   111	                            role={CONST.ROLE.PRESENTATION}
   112	                            defaultValue={currentUserDetails.lastName ?? ''}
   113	                            spellCheck={false}
   114	                        />
   115	                    </View>
   116	                </FormProvider>
   117	        </ScreenWrapper>
   118	    );
   119	}
